import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.baksmali.*;import com.android.tools.smali.baksmali.Adaptors.*;import com.android.tools.smali.baksmali.formatter.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;import java.util.regex.*;
class VerifyBoxOfficeEndpoint {
 static final Set<String> classes=Set.of("Ln9/b;","Lsa/b0$a;","Lsa/o0;");
 static boolean allowed(String cls,String sig){if(cls.equals("Ln9/b;"))return sig.contains(" b()Ljava/lang/String;");if(cls.equals("Lsa/b0$a;"))return sig.contains(" intercept(");return cls.equals("Lsa/o0;")&&(sig.contains(" R()Ljava/lang/String;")||sig.contains(" a1(Ljava/lang/String;)V"));}
 static String text(ClassDef def)throws Exception{StringWriter s=new StringWriter();BaksmaliOptions o=new BaksmaliOptions();o.sequentialLabels=true;o.debugInfo=true;BaksmaliWriter w=new BaksmaliWriter(s);new ClassDefinition(o,def).writeTo(w);w.flush();return s.toString();}
 static Map<String,String> methods(String s){Map<String,String> r=new TreeMap<>();Matcher m=Pattern.compile("(?ms)^\\.method([^\\n]*)\\n.*?^\\.end method").matcher(s);while(m.find())r.put(m.group(1),m.group());return r;}
 static String stripMethods(String s){return s.replaceAll("(?ms)^\\.method[^\\n]*\\n.*?^\\.end method","");}
 public static void main(String[]args)throws Exception{int total=0,changed=0,newClasses=0;List<String> report=new ArrayList<>();
 try(ZipFile a=new ZipFile(args[0]);ZipFile b=new ZipFile(args[1])){for(var es=a.entries();es.hasMoreElements();){var e=es.nextElement();if(!e.getName().matches("classes[0-9]*\\.dex"))continue;byte[] old=a.getInputStream(e).readAllBytes(),now=b.getInputStream(b.getEntry(e.getName())).readAllBytes();DexBackedDexFile before=new DexBackedDexFile(old,0),after=new DexBackedDexFile(now,0);if(Arrays.equals(old,now)){total+=before.classCount;continue;}Map<String,ClassDef> defs=new HashMap<>();for(int i=0;i<after.classCount;i++){ClassDef d=(ClassDef)after.classSection.get(i);defs.put(d.getType(),d);}for(int i=0;i<before.classCount;i++){ClassDef d=(ClassDef)before.classSection.get(i);ClassDef n=defs.remove(d.getType());if(n==null)throw new IllegalStateException("Removed class");String x=text(d),y=text(n);total++;if(x.equals(y))continue;if(!classes.contains(d.getType()))throw new IllegalStateException("Unexpected changed class: "+d.getType());if(!stripMethods(x).equals(stripMethods(y)))throw new IllegalStateException("Unexpected fields/metadata change: "+d.getType());Map<String,String> xm=methods(x),ym=methods(y);if(!xm.keySet().equals(ym.keySet()))throw new IllegalStateException("Method declarations changed");for(String sig:xm.keySet())if(!xm.get(sig).equals(ym.get(sig))){if(!allowed(d.getType(),sig))throw new IllegalStateException("Unexpected method change: "+d.getType()+sig);report.add(e.getName()+"\t"+d.getType()+"\t"+sig);}changed++;}
 for(String added:defs.keySet()){if(!added.equals("Lcom/mgs/carparking/util/IndiaDisplayLabels;"))throw new IllegalStateException("Unexpected new class "+added);newClasses++;}System.out.println("Canonical verification passed: "+e.getName());
 }}if(changed!=3||newClasses!=0||report.size()!=4)throw new IllegalStateException("Unexpected class counts: "+changed+" / "+newClasses);Files.write(Path.of(args[2]),report);System.out.println("Classes checked="+total+"; expected modified classes="+changed+"; new display helper="+newClasses+"; changed methods="+report.size());}
}
